export const AUDIO_KEY='filament-atelier:audio:v1';
export const DEFAULT_AUDIO={enabled:true,master:40,effects:65,ambience:35,music:false};
export function normalizeAudio(a={}){const out={...DEFAULT_AUDIO};for(const k of ['master','effects','ambience'])out[k]=Number.isFinite(Number(a[k]))?Math.max(0,Math.min(100,Number(a[k]))):out[k];out.enabled=a.enabled!==false;out.music=a.music===true;return out;}
export class WorkshopAudio{
 constructor({storage=globalThis.localStorage,Context=globalThis.AudioContext||globalThis.webkitAudioContext,onChange=()=>{}}={}){this.storage=storage;this.Context=Context;this.onChange=onChange;this.prefs={...DEFAULT_AUDIO};try{this.prefs=normalizeAudio(JSON.parse(storage.getItem(AUDIO_KEY)||'{}'));}catch{}this.ctx=null;this.error=false;this.active=false;this.hidden=false;this.world={playing:false,busy:0,working:false};this.lastEffect=-100;this.lastNotice=-100;this.lastLog=null;this.lastMusic=-100;this.voices=new Set();}
 async unlock(){if(!this.prefs.enabled||this.error)return false;try{if(!this.ctx){if(!this.Context)throw Error('Web Audio indisponible');this.ctx=new this.Context();this.master=this.ctx.createGain();this.fx=this.ctx.createGain();this.room=this.ctx.createGain();this.music=this.ctx.createGain();const limiter=this.ctx.createDynamicsCompressor();limiter.threshold.value=-18;limiter.knee.value=16;limiter.ratio.value=5;limiter.attack.value=.006;limiter.release.value=.18;this.fx.connect(this.master);this.room.connect(this.master);this.music.connect(this.master);this.master.connect(limiter);limiter.connect(this.ctx.destination);this.buffer=this.ctx.createBuffer(1,this.ctx.sampleRate*2,this.ctx.sampleRate);const samples=this.buffer.getChannelData(0);for(let i=0;i<samples.length;i++)samples[i]=(Math.random()*2-1)*.45;this.buildAmbience();}if(this.ctx.state==='suspended')await this.ctx.resume();this.active=this.ctx.state==='running';this.apply();this.onChange();return this.active;}catch{this.error=true;this.active=false;this.onChange();return false;}}
 status(){return this.error?'Son indisponible sur ce navigateur':!this.prefs.enabled?'Son coupé':this.active?'Son actif':'Le son démarre au premier clic';}
 set(key,value){if(!(key in DEFAULT_AUDIO))return;this.prefs=normalizeAudio({...this.prefs,[key]:value});try{this.storage.setItem(AUDIO_KEY,JSON.stringify(this.prefs));}catch{}this.apply();if(this.prefs.enabled)this.unlock();this.onChange();}
 ramp(param,value,time=.15){if(!this.ctx)return;param.cancelScheduledValues(this.ctx.currentTime);param.setTargetAtTime(value,this.ctx.currentTime,time);}
 apply(){if(!this.ctx)return;const p=this.prefs,live=this.active&&p.enabled&&!this.hidden;this.ramp(this.master.gain,live?p.master/100:0,.035);this.ramp(this.fx.gain,p.effects/100,.03);this.ramp(this.music.gain,p.music&&this.world.playing?.20:0,.12);this.ramp(this.room.gain,this.world.playing?p.ambience/100:0,.12);this.ramp(this.motorGain.gain,this.world.busy?Math.min(.045,.015+this.world.busy*.007):0,.3);this.ramp(this.airGain.gain,this.world.playing?.006:0,.3);}
 buildAmbience(){const c=this.ctx;this.air=c.createBufferSource();this.air.buffer=this.buffer;this.air.loop=true;const filter=c.createBiquadFilter();filter.type='lowpass';filter.frequency.value=650;this.airGain=c.createGain();this.airGain.gain.value=0;this.air.connect(filter);filter.connect(this.airGain);this.airGain.connect(this.room);this.air.start();this.motor=c.createOscillator();this.motor.type='sine';this.motor.frequency.value=116;this.motorGain=c.createGain();this.motorGain.gain.value=0;this.motor.connect(this.motorGain);this.motorGain.connect(this.room);this.motor.start();}
 note(hz,delay=0,duration=.15,amplitude=.08,bus=this.fx,type='sine'){if(!this.ctx)return;const c=this.ctx,t=c.currentTime+delay,source=c.createOscillator(),gain=c.createGain();source.type=type;source.frequency.setValueAtTime(hz,t);gain.gain.setValueAtTime(0,t);gain.gain.linearRampToValueAtTime(amplitude,t+.009);gain.gain.exponentialRampToValueAtTime(.0001,t+duration);source.connect(gain);gain.connect(bus);this.voices.add(source);source.onended=()=>{source.disconnect();gain.disconnect();this.voices.delete(source);};source.start(t);source.stop(t+duration+.02);}
 rustle(duration=.09,amplitude=.045,frequency=1600){const c=this.ctx,t=c.currentTime,source=c.createBufferSource(),filter=c.createBiquadFilter(),gain=c.createGain();source.buffer=this.buffer;filter.type='bandpass';filter.frequency.value=frequency;filter.Q.value=.7;gain.gain.setValueAtTime(amplitude,t);gain.gain.exponentialRampToValueAtTime(.0001,t+duration);source.connect(filter);filter.connect(gain);gain.connect(this.fx);this.voices.add(source);source.onended=()=>{source.disconnect();filter.disconnect();gain.disconnect();this.voices.delete(source);};source.start(t);source.stop(t+duration+.02);}
 play(kind='click'){if(!this.active||!this.prefs.enabled||this.hidden||!this.ctx||this.ctx.state!=='running')return false;const now=this.ctx.currentTime,notice=['mail','complete','delivery','warning'].includes(kind);if(now-this.lastEffect<.075||notice&&now-this.lastNotice<1.5||this.voices.size>20)return false;this.lastEffect=now;if(notice)this.lastNotice=now;
 if(kind==='mail'){this.note(659,0,.36,.065);this.note(880,.13,.46,.055);}
 else if(kind==='complete'||kind==='delivery'){this.note(523,0,.24,.07);this.note(659,.10,.25,.06);this.note(784,.20,.4,.055);}
 else if(kind==='warning'){this.note(220,0,.17,.06);this.note(185,.12,.25,.045);}
 else if(kind==='place'){this.rustle(.15,.075,900);this.note(155,0,.12,.09,this.fx,'triangle');}
 else if(kind==='ship'){this.rustle(.24,.07,2100);this.note(392,.08,.23,.06);}
 else{this.note(kind==='wardrobe'?740:480,0,.065,.035,this.fx,'triangle');this.rustle(.035,.025,1900);}
 return true;
 }
 update(world,s){this.world=world;this.apply();if(s){if(this.lastLog===null||s.nextId<this.lastLog)this.lastLog=s.nextId-1;const logs=s.log.filter(l=>l.id>this.lastLog);this.lastLog=s.nextId-1;const picked=logs.find(l=>l.type==='warning')||logs.find(l=>/Livraison|Approvisionnement/.test(l.text))||logs.find(l=>l.type==='client')||logs.find(l=>/terminée|prêt à expédier|Maîtrise/.test(l.text));if(picked)this.play(picked.type==='warning'?'warning':picked.type==='client'?'mail':/Livraison|Approvisionnement/.test(picked.text)?'delivery':'complete');}if(this.active&&this.prefs.music&&this.world.playing&&!this.hidden&&this.ctx.currentTime-this.lastMusic>9){this.lastMusic=this.ctx.currentTime;[261.63,329.63,392,523.25].forEach((hz,i)=>this.note(hz,i*.8,1.5,.045,this.music));}}
 setHidden(hidden){this.hidden=hidden;this.apply();}
 dispose(){this.active=false;this.air?.stop();this.motor?.stop();for(const v of this.voices)v.stop();this.voices.clear();this.ctx?.close();}
}
